insert into q(q_act,qname,qdesc) values(@actid,N'ABI/INFORM Collection',N'The most comprehensive ABI/INFORM™ database, this comprises ABI/INFORM Global, ABI/INFORM Trade and Industry, and ABI/INFORM Dateline. The database features thousands of full-text journals, dissertations, working papers, key business and economics periodicals such as the Economist, country-and industry-focused reports, and downloadable data. Its international coverage gives researchers a complete picture of companies and business trends around the world.')
insert into q(q_act,qname,qdesc) values(@actid,N'Academic Search Premier',N'A popular resource found in many scholarly settings worldwide, Academic Search Premier is a leading multidisciplinary research database. It provides acclaimed full-text journals, magazines, and other valuable resources that cover the expansive academic disciplines offered in colleges and universities. This comprehensive content includes both PDF backfiles and searchable cited references.')
insert into q(q_act,qname,qdesc) values(@actid,N'AccessAPN',N'AccessAPN is a comprehensive online resource from McGraw Hill in partnership with Sigma Theta Tau. The database features a wide range of content of interest to students in Advanced Practice Nursing programs, as well as other nursing programs, public health, and health administration programs.')
insert into q(q_act,qname,qdesc) values(@actid,N'AccessEmergency Medicine',N'AccessEmergency Medicine provides medical students with a variety of resources needed to excel on their clerkship; assists residents in gaining instant access to videos, self-assessment, and leading emergency textbooks that will establish an important foundation for learning; and allows practicing physicians to brush up on their medical knowledge when studying for their recertification exam.')
insert into q(q_act,qname,qdesc) values(@actid,N'AccessMedicine',N'AccessMedicine provides medical students with a variety of resources needed to excel in basic science studies and clerkships; helps residents, nurse practitioners, and physician assistants with instant access to videos, self-assessment, and leading medical textbooks that facilitate decision-making at the point-of-care; and allows practicing physicians to brush up on their medical knowledge to ensure the best patient outcome.')
insert into q(q_act,qname,qdesc) values(@actid,N'AccessPediatrics',N'AccessPediatrics can help medical students to excel in their clerkship through use of use videos, cases, and Q&A assist residents with leading pediatric textbooks and vignette style exam prep that will establish an important foundation for future practice, and allow practicing pediatricians to quickly search for relevant  clinical information.')
insert into q(q_act,qname,qdesc) values(@actid,N'AccessSurgery',N'AccessSurgery provides medical students with a variety of resources needed to excel in their surgery clerkship; assists residents in gaining instant access to videos, self-assessment, and leading surgical textbooks that will establish an important foundation for learning; and allows practicing surgeons to brush up on their medical knowledge when studying for their Maintenance of Certification Exam.')
insert into q(q_act,qname,qdesc) values(@actid,N'Accounting, Tax, and Banking Collection',N'Quickly locate precise results from sources ranging from current news to professional and academic journal articles covering the trends and history influencing important accounting, tax, banking, and financial issues of the day.')
insert into q(q_act,qname,qdesc) values(@actid,N'Advanced Technologies and Aerospace Database',N'Includes coverage of aeronautics, astronautics, communications, computer and information technology, electronics, lasers, solid-state materials and devices, space sciences, and telecommunications. The Advanced Technologies and Aerospace Database includes the renowned Aerospace Database and provides full-text titles from around the world, including scholarly journals, trade and industry journals, magazines, technical reports, conference proceedings, and government publications.')
insert into q(q_act,qname,qdesc) values(@actid,N'African-American Poetry (1750-1900)',N'The early history of African American poetry, from the first recorded poem by an African American (Lucy Terry Prince''s ''Bars Fight'', c.1746) to the major poets of the nineteenth century, including Paul Laurence Dunbar and Frances Ellen Watkins Harper.')
insert into q(q_act,qname,qdesc) values(@actid,N'African-American Poetry (20th Century)',N'A database of modern and contemporary African American poetry, featuring almost 9,000 poems by 62 of the most important African American poets of the last century, including Langston Hughes, Jean Toomer, Imamu Amiri Baraka, Audre Lorde, and Rita Dove.')
insert into q(q_act,qname,qdesc) values(@actid,N'Agricultural and Environmental Science Collection',N'This interdisciplinary collection merges abstracts, citations, full-text scholarly journals, and other research materials from hundreds of reputable publishers. Coverage (1960-Current Day) is broad including subjects such as agronomy, soil science, crop management, environmental sustainability, forestry, horticulture, and natural resource management. Within the database, users can access peer-reviewed literature, conference proceedings, trade journals, reports, dissertations, and other research outputs that offer critical insights and the latest developments in their fields.')
insert into q(q_act,qname,qdesc) values(@actid,N'American Civil War Letters and Diaries',N'This collection contains 2,009 authors and approximately 100,000 pages of diaries, letters, and memoirs. Particular care has been taken to index this material so it can be searched more thoroughly than ever. Each source has been carefully chosen using leading bibliographies. The database includes 4,000 pages of previously unpublished manuscripts, such as the letters of Amos Wood and his wife and the diary of Maryland Planter, William Claytor. The collection also includes biographies, an extensive bibliography of the sources in the database, and material licensed from The Civil War Day-by-Day by E.B. Long.')
insert into q(q_act,qname,qdesc) values(@actid,N'American Poetry (1600-1900)',N'American Poetry contains over 40,000 poems by more than 200 poets, covering the Colonial period to the early twentieth century, and drawn from over 1,200 printed sources.')
insert into q(q_act,qname,qdesc) values(@actid,N'American Poetry (20th century)',N'This unparalleled collection includes 50,000 poems drawn from 750 volumes by over 300 poets, including Adrienne Rich, Andrei Codrescu, Ezra Pound, William Carlos Williams, Denise Levertov, Wallace Stevens, Langston Hughes, Lucille Clifton, and Cathy Song.')
insert into q(q_act,qname,qdesc) values(@actid,N'American Revolution',N'Consisting of 450 titles totaling 94,000 pages of text, Introduction to U.S. History: The American Revolution was selected and edited by Professor Katherine Hermes of Central Connecticut State University.
insert into q(q_act,qname,qdesc) values(@actid,N'Annual Reviews, 1932-2025',N'Critical reviews with a focus on Biomedical, Physical, and Social Sciences.')
insert into q(q_act,qname,qdesc) values(@actid,N'Applied and General Science Database',N'Whether you are researching the effects of global warming or interested in the latest scandal surrounding genetically modified food, ProQuest Science Journals will guide you directly to the information you need. ProQuest Science Journals provides unmatched research support for both the applied and general sciences. Perfect for students in academic research environments, this impressive collection of scientific journals offers users a one-stop resource for their research needs. With coverage dating back to 1986, ProQuest Science Journals features over 1,145 titles—with more than 965 available in full text. In full-text format, researchers have access to all the charts, diagrams, graphs, tables, photos, and other graphical elements so vital to scientific and technical literature.')
insert into q(q_act,qname,qdesc) values(@actid,N'Archived LRU Publications Online',N'Publications and other records of Lenoir-Rhyne''s history.')
insert into q(q_act,qname,qdesc) values(@actid,N'ArchiveGrid',N'ArchiveGrid includes over 7 million records describing archival materials, bringing together information about historical documents, personal papers, family histories, and more. With over 1,400 archival institutions represented, ArchiveGrid helps researchers looking for primary source materials held in archives, libraries, museums and historical societies.')
insert into q(q_act,qname,qdesc) values(@actid,N'Art and Architecture Complete',N'Art and Architecture Complete offers 204 active full-text art journals and magazines, plus thousands of images. Beneficial for artists, scholars, and designers, it encompasses fine, decorative, and commercial art, as well as architecture and architectural design.')
insert into q(q_act,qname,qdesc) values(@actid,N'Arts and Humanities Database',N'Features hundreds of titles covering Art, Architecture, Design, History, Philosophy, Music, Literature, Theatre and Cultural Studies.')
insert into q(q_act,qname,qdesc) values(@actid,N'Asian and European Business Collection',N'This database provides information pertinent to the study of business and finance topics across Asia and Europe, including academic journals, newspapers, newswires, and magazines. Find information on companies, economies, markets, international trade, and overall business conditions and practices throughout these regions.')
insert into q(q_act,qname,qdesc) values(@actid,N'ATLA Religion',N'An index to journal articles, book reviews, and collections of essays in all fields of religion.')
insert into q(q_act,qname,qdesc) values(@actid,N'Australia and New Zealand Database',N'This database provides ongoing full-text academic journals that are locally published by scholarly publishing organizations and educational institutions in Australia and New Zealand. Major subject areas of study are represented, including business, science, technology, engineering, social sciences, education, and humanities.')
insert into q(q_act,qname,qdesc) values(@actid,N'Biological Science Database',N'This interdisciplinary database offers abstracts and citations to a wide range of research in biomedicine, biotechnology, zoology and ecology, with some aspects of agriculture and veterinary science. Supporting over two dozen areas of expertise, this database provides access to literature from over 6,000 serials, as well as conference proceedings, technical reports, monographs and selected books and patents.')
insert into q(q_act,qname,qdesc) values(@actid,N'Bloomsbury Collections',N'Bloomsbury Collections offers excellence and originality in scholarship across the arts, humanities, and social sciences. Discover our ever-expanding eBook library with more than 30,000 titles across 45+ subject areas. Subjects include: African Studies, Architecture, Art and Visual Culture, Biblical Studies, Classical Studies and Archaeology, Design, Education, Fashion, Film and Media, History, Law, Linguistics, Literary Studies, Middle East, Music and Sound Studies, Philosophy, Politics and International Relations, Religious Studies, Sociology, Theology')
insert into q(q_act,qname,qdesc) values(@actid,N'Business Market Research Collection',N'Business, Economics, and Market Research: Business Market Research Collection includes company and industry reports from a variety of sources including Hoover''s Company Profiles, Barnes Reports and First Research.')
insert into q(q_act,qname,qdesc) values(@actid,N'Business Source Premier',N'This database offers an intuitive and efficient platform for exploring country economic data, company profiles, industry insights, and market research.')
insert into q(q_act,qname,qdesc) values(@actid,N'Canadian Business and Current Affairs Database',N'This database is a longstanding, comprehensive Canadian periodical collection covering multiple subjects and topics, with millions of full-text records. Accessible to readers and researchers at every level, the Canadian Business and Current Affairs Database features a diversified mix of publications, including scholarly journals, trade publications, magazines, reports, radio and television transcripts, news, dissertations, and more.')
insert into q(q_act,qname,qdesc) values(@actid,N'Canadian Newsstream',N'This database offers unparalleled access to the full text of over 400 Canadian news sources from Canada''s leading publishers. This full text database includes the complete available electronic backfile for most newspapers, providing full access to the articles, columns, editorials and features published in each. Most titles are updated daily and some backfiles date as far back as the late 1970s.')
insert into q(q_act,qname,qdesc) values(@actid,N'Career and Technical Education Database',N'ProQuest Career and Technical Education is the definitive source for vocational information. The database includes nearly 600 titles, with more than 500 available in full text for quick access to research on virtually any technical topic.')
insert into q(q_act,qname,qdesc) values(@actid,N'Chronicle of Higher Education',N'The Chronicle of Higher Education is academe’s most trusted resource for independent journalism, career development, and forward-looking intelligence. Since its founding in 1966, The Chronicle has grown to serve millions of educators, administrators, researchers, and policymakers who rely on its insights to lead, teach, learn, and innovate. The Chronicle’s independent newsroom – the nation’s largest dedicated to covering colleges and universities – is home to award-winning journalists and data analysts with a passion for serving audiences with indispensable news and actionable insights on issues that matter.')
insert into q(q_act,qname,qdesc) values(@actid,N'CINAHL Complete',N'CINAHL Complete is a comprehensive database offering convenient access to 717 active full-text journals spanning various disciplines in nursing and allied health, along with evidence-based care sheets, quick lessons, and more.CINAHL Subject Headings help users effectively search and retrieve information and follow the structure of the Medical Subject headings (MeSH) used by the National Library of Medicine. These Subject Headings help researchers find new concepts, including COVID-19, social distancing and vaping as well as local terminology.')
insert into q(q_act,qname,qdesc) values(@actid,N'Civil War',N'Consisting of nearly 500 titles totaling about 90,000 pages of text, Introduction to U.S. History: The Civil War was selected and edited by Professor Paul Finkelman of the Albany Law School.
insert into q(q_act,qname,qdesc) values(@actid,N'Computer Science Database',N'Scholarly journals, trade publications, and consumer titles covering topics such as artificial intelligence, gaming, graphics, networking, security, database management, and systems administration.')
insert into q(q_act,qname,qdesc) values(@actid,N'Consumer Health Database',N'This database includes journals and magazines covering an enormous range of health subjects, from sports injuries to women''s health, from food and nutrition to midwifery, from eye care to dentistry.')
insert into q(q_act,qname,qdesc) values(@actid,N'Consumer Reports',N'Consumer Reports is a nonprofit organization providing unbiased product ratings and reviews. Consumer Reports, formerly Consumers Union, is an American nonprofit consumer organization dedicated to independent product testing, investigative journalism, consumer-oriented research, public education, and consumer advocacy.')
insert into q(q_act,qname,qdesc) values(@actid,N'Continental Europe Database',N'This database provides ongoing full-text academic journals that are locally published by scholarly publishing organizations and educational institutions in many European countries, including France, Italy, Germany, Denmark, Norway, Sweden, Switzerland, Spain, and Portugal. Major subject areas of study are represented, including business, science, technology, engineering, social sciences, education, and humanities.')
insert into q(q_act,qname,qdesc) values(@actid,N'CQ Researcher',N'CQ Researcher is the choice of students and librarians for a balanced view of today''s most pressing social, political, and economic issues. Each weekly report covers the given topic in a non-sensationalized manner, and many reports feature a pro/con debate, highlighting both sides of the argument.')
insert into q(q_act,qname,qdesc) values(@actid,N'Credo Reference',N'This database is ideal for students starting their research or learning about the research process during information literacy instruction. With hundreds of searchable, full-text titles from the world’s foremost publishers, Credo Reference covers every major subject.')
insert into q(q_act,qname,qdesc) values(@actid,N'Criminal Justice Database',N'Criminal Justice Database is a comprehensive database supporting research on crime, its causes and impacts, legal and social implications, as well as litigation and crime trends. As well as U.S. and international scholarly journals, it includes correctional and law enforcement trade publications, dissertations, crime reports, crime blogs and other material relevant for researchers or those preparing for careers in criminal justice, law enforcement and related fields.')
insert into q(q_act,qname,qdesc) values(@actid,N'Data-Axle Reference Solutions',N'Data Axle is an industry leader in business and consumer information. It is an online tool to give access to data on over 17 million businesses and 320 million consumers. This resource eliminates the need to scour multiple websites or perform complicated searches.')
insert into q(q_act,qname,qdesc) values(@actid,N'Digital North Carolina',N'DigitalNC is a project of the North Carolina Digital Heritage Center, a statewide digitization and digital publishing program that works with cultural heritage organizations of all sizes across North Carolina to digitize and publish historic materials online.')
insert into q(q_act,qname,qdesc) values(@actid,N'Digital Public Library of America',N'The Digital Public Library of America amplifies the value of libraries and cultural organizations as Americans’ most trusted sources of shared knowledge. We do this by collaborating with partners to accelerate innovative tools and ideas that empower and equip libraries to make information more accessible. They make millions of materials from libraries, archives, museums, and other cultural institutions across the country available to all in a one-stop discovery experience.')
insert into q(q_act,qname,qdesc) values(@actid,N'Early American Imprints, Series I: Evans, 1693-1800',N'This resource documents the relationships among peoples in North America from 1534 to 1850. The collection focuses on personal accounts and provides unique perspectives from all of the protagonists, including traders, slaves, missionaries, explorers, soldiers, native peoples, and officials, both men and women. The project brings coherence to a wide range of published and unpublished accounts, including narratives, diaries, journals, and letters.')
insert into q(q_act,qname,qdesc) values(@actid,N'Early Encounters in North America',N'Letters, diaries, and documents tracing relationships among people and cultures, from 1534 to 1850.')
insert into q(q_act,qname,qdesc) values(@actid,N'Earth, Atmospheric, and Aquatic Science Database',N'A full text interdisciplinary resource of scholarly and learned material with a particular focus on geoscience, meteorology, climatology, aquatic science, and related disciplines. Coverage includes thousands of full-text publications including peer-reviewed journals, trade publications, dissertations, conference proceedings, reports, video material, and much more.')
insert into q(q_act,qname,qdesc) values(@actid,N'East and Central Europe Database',N'The East and Central Europe Database features full-text academic journals that are locally published by scholarly publishing organizations and educational institutions located in the East and Central Europe region. Major subject areas of study are represented, including business, science, technology, engineering, medical, social sciences, education, arts, literature, history, and others.')
insert into q(q_act,qname,qdesc) values(@actid,N'East and South Asia Database',N'This database provides ongoing full-text academic journals that are locally published by scholarly publishing organizations and educational institutions in many East Asian and South Asian countries. Major subject areas of study are represented, including business, science, technology, engineering, social sciences, education, and humanities.')
insert into q(q_act,qname,qdesc) values(@actid,N'eBook Central',N'ebook Central delivers with a breadth and depth of eBooks from scholarly sources, including university presses and other top publishers.')
insert into q(q_act,qname,qdesc) values(@actid,N'eBooks - EBSCO',N'Online access to thousands of print books, including fiction and non-fiction titles.')
insert into q(q_act,qname,qdesc) values(@actid,N'Economist',N'From its beginnings in 1843, when The Economist newspaper was founded by a Scottish hat manufacturer to further the cause of free trade, The Economist Group has evolved into a staunchly independent global media and information-services company with intelligent brands for an international audience. Over time, the newspaper has helped readers grasp the great drivers of change, from technology to geopolitics, finance and economics. It added a dedicated section on the United States in 1942 and a China section in 2012. It expanded successfully into North America, which became its largest market. To serve decision-makers in businesses and beyond, the Economist Intelligence Unit (EIU) became a leader in country analysis and forecasting. Live events around the world brought global thought-leaders together to discuss critical topics at roundtables and summits. In recent years, the great change has been digital. The EIU started to deliver a timely stream of business intelligence and data. The Economist expanded its journalism online, onto its app and into podcasts, films, interactive infographics and social media. Economist Education began online executive courses, and Economist Impact grew, combining the reach and rigor of a think-tank with the creativity of a media brand to engage influential stakeholders and find new ways to pursue progress.')
insert into q(q_act,qname,qdesc) values(@actid,N'Education Database',N'Education Database supports the study and application of education across all levels of education, including early childhood education, primary and secondary education, and higher education. The database supports global study and research, including thousands of full-text journals, dissertations and other relevant sources.')
insert into q(q_act,qname,qdesc) values(@actid,N'eLibrary',N'A massive, multidisciplinary database, designed for students and educators at high schools, community colleges, and four-year universities. Editorially created pages provide valuable context for both common and obscure research topics. The content, which is all full text, includes books, magazines, journals, newspapers, photographs, transcripts, and videos.')
insert into q(q_act,qname,qdesc) values(@actid,N'Encyclopedia of Social Work',N'Co-published by the National Association of Social Workers and Oxford University Press, the 20th edition of the Encyclopedia of Social Work is widely considered the cornerstone of reference in its field. This new edition includes coverage of areas that have come to the fore since the 1995 publication of the 19th edition, including demographic changes from immigration, technology, the implications of managed care, faith-based assistance, evidence-based practice, gerontology, and trauma and disaster.')
insert into q(q_act,qname,qdesc) values(@actid,N'Encyclopedia of the Life Sciences',N'Reference work updated monthly containing specially commissioned, peer-reviewed and citable articles written by leaders in biology and related fields.')
insert into q(q_act,qname,qdesc) values(@actid,N'Engineering Journals Database',N'Contains engineering-related full-text articles and a comprehensive index to world literature on technological and engineering innovations going back to 1966. It provides titles from around the world including scholarly journals, trade and industry journals, magazines, technical reports, and more.')
insert into q(q_act,qname,qdesc) values(@actid,N'English Poetry (20th century)',N'A collection of 598 volumes of poetry by 283 poets from 1900 to 2000, including W.B. Yeats, Rudyard Kipling, Thomas Hardy, Wilfred Owen, Thom Gunn, Fleur Adcock, Paul Muldoon, Tony Harrison, Benjamin Zephaniah and Carol Ann Duffy, and incorporating poets from The Faber Poetry Library.')
insert into q(q_act,qname,qdesc) values(@actid,N'English Poetry (600-1900)',N'The original ground-breaking Chadwyck-Healey collection, English Poetry contains essentially the complete English poetic canon from the 8th century to the early 20th. Over 160,000 poems by more than 1,250 poets are drawn from nearly 4,500 printed sources.')
insert into q(q_act,qname,qdesc) values(@actid,N'Entrepreneurial Studies Source',N'Covering the latest insights in entrepreneurship and small business ownership, Entrepreneurial Studies Source is an essential full-text database for business students and researchers. It offers hundreds of full-text journals and books, plus company profiles and videos.')
insert into q(q_act,qname,qdesc) values(@actid,N'Entrepreneurship Database',N'This database bridges theory with practice, covering a wide spectrum of resources useful to educators, researchers, students and practitioners. Content ranges from the scholarly - including journals, dissertations, working papers and conference proceedings - to a full toolkit of practical guides, templates, forms, sample business plans and tips from successful entrepreneur in a wide range of formats - from video to downloadable Word and Excel files, as well as traditional text and PDFs.')
insert into q(q_act,qname,qdesc) values(@actid,N'Environment Complete',N'Environment Complete is a leading full-text database for environmental studies. It provides hundreds of top environment journals covering ecosystem ecology, energy, environmental policy, sustainability and other related subjects.')
insert into q(q_act,qname,qdesc) values(@actid,N'ERIC (Education)',N'ERIC (Education Resources Information Center) is an authoritative database of indexed and full-text education literature and resources. Sponsored by the Institute of Education Sciences of the U.S. Department of Education, it is an essential tool for education researchers of all kinds.')
insert into q(q_act,qname,qdesc) values(@actid,N'Exploring Race in Society',N'Offers essential content covering important issues related to race in society today. Essays, articles, reports and other reliable sources provide an in-depth look at the history of race and provide critical context for learning more about topics associated with race, ethnicity, diversity and inclusiveness.')
insert into q(q_act,qname,qdesc) values(@actid,N'Faber Poetry Library',N'The Faber Poetry Library contains the works of 50 poets comprising 140 volumes of poetry. The authors are all part of the Faber Poetry list and the database enjoys the active support of the publisher and the poets or their estates. Authors covered include Simon Armitage, Rupert Brooke, Wendy Cope, T. S. Eliot, Lavinia Greenlaw, Thom Gunn, Seamus Heaney, Ted Hughes, David Jones, Louis MacNeice, Andrew Motion, Paul Muldoon, Tom Paulin, Sylvia Plath, Siegfried Sassoon, Stephen Spender and Edward Thomas.')
insert into q(q_act,qname,qdesc) values(@actid,N'Ferguson''s Career Guidance Center',N'Ferguson’s Career Guidance Center is an award-winning reference database for lifelong career exploration and planning. It offers a wealth of resources for users to assess their career goals and interests, plan their education, learn workplace skills, find apprenticeships and internships, conduct a job search, and much more. It provides users with clean, fast access to core content; a fully responsive design; a seamless multimedia experience; unparalleled, up-to-date information; proprietary directories of apprenticeships and internships; and financial aid and school search databases. For students choosing a career path, graduates entering the workforce, or professionals changing careers, Ferguson’s Career Guidance Center supports users at every step of their career journey.')
insert into q(q_act,qname,qdesc) values(@actid,N'Films on Demand',N'A comprehensive, instruction-focused streaming video subscription that offers every student and academic department on campus unlimited access to the most essential videos for their field of study. Includes exceptional content from the world’s top producers, such as PBS, BBC, National Geographic, and HBO. All Films On Demand collections include unlimited views, a full statistical suite, and tools to create clips, share playlists, and build in-video assessments.')
insert into q(q_act,qname,qdesc) values(@actid,N'Gale eBooks',N'Electronic database of encyclopedias, almanacs, and specialized reference sources for multidisciplinary subjects.')
insert into q(q_act,qname,qdesc) values(@actid,N'Gender Studies Database',N'Gender Studies Database provides indexing and abstracts covering the full spectrum of gender-related scholarship inside and outside academia. It indexes scholarly and popular publications including journals, books, conference papers and theses.')
insert into q(q_act,qname,qdesc) values(@actid,N'Global Breaking Newswires',N'In the modern news world, newswires are the chief source of timely news and, with increasing pressures on the traditional news industry, newswires are often the only news coverage for many large regions of the globe. Global Breaking Newswires is the premier library news product providing timely access to the best newswire content available from around the globe for the modern researcher as well as growing archive of news indexed and accessible through the familiar and popular research functionality of the ProQuest platform.')
insert into q(q_act,qname,qdesc) values(@actid,N'GreenFILE',N'GreenFILE is a free research database covering all aspects of human impact to the environment. Its collection of scholarly, government and general-interest titles includes content on global warming, green building, pollution, sustainable agriculture, renewable energy, recycling, and more.')
insert into q(q_act,qname,qdesc) values(@actid,N'Health and Medical Collection',N'The journals cover all major clinical and healthcare disciplines, including medical sciences, immunology, pharmacy and pharmacology, nursing, physical fitness and hygiene, surgery, and others.')
insert into q(q_act,qname,qdesc) values(@actid,N'Health Source: Consumer Edition',N'This full-text database covers a wide variety of subjects, including information on specific diseases as well as overall health topics from consumer health magazines and reference materials. Subjects Include: Fitness, nutrition, diabetes, aging, women''s health, children''s health, and more.')
insert into q(q_act,qname,qdesc) values(@actid,N'Health Source: Nursing/Academic Edition',N'Health Source: Nursing/Academic Edition is a trusted full-text database covering nursing and allied health topics, including pediatric nursing, critical care, mental health, nursing management, medical law and more.')
insert into q(q_act,qname,qdesc) values(@actid,N'Healthcare Administration Database',N'This high-demand healthcare management content provides the most reliable and relevant information on a wide range of topics, including: Hospitals. insurance, law, statistics, business management, personnel management, ethics, health economics, and public health administration. This source provides coverage for around 800 key journals with over 4,500 Doctoral Dissertations and Theses, ProQuest Health Management provides users with the highest quality content, much of which is not available elsewhere.')
insert into q(q_act,qname,qdesc) values(@actid,N'HeritageQuest',N'Discover the amazing history of you with HeritageQuest Online. With more than 5 billion records, it delivers an essential collection of genealogical and historical sources—with coverage dating back to the 1700s—that can help people find their ancestors and discover a place’s past.')
insert into q(q_act,qname,qdesc) values(@actid,N'Historic North Carolina Digital Newspaper Collection',N'3.5 million pages of digitized content from over 1,000 NC county newspapers.')
insert into q(q_act,qname,qdesc) values(@actid,N'History Study Center',N'History Study Center (HSC) is a curated collection of full-text journals, popular magazines and primary source documents covering a range of global historical topics and themes. The collection includes current and archival secondary sources for vital content and varied perspectives on thousands of topics from world history. Users can explore primary source documents from three U.S. Presidential Administrations, offering insights into mid-20th Century landmark events that reverberate into the current day. HSC supports students preparing to complete the Cambridge International AS and A Level Global Perspectives & Research project, as well as completion of the Advanced Placement U.S. History and Advanced Placement World History examinations and course work. It’s also a trusted companion for a National History Day project.')
insert into q(q_act,qname,qdesc) values(@actid,N'Home Grown eBook Collection',N'eBooks from North Carolina publishers and authors. Includes fiction, nonfiction and poetry.')
insert into q(q_act,qname,qdesc) values(@actid,N'Hoopla',N'Downloadable audio, eBooks, comics, and movies on a variety of topics including language learning, history, biography, classic literature, and more. Compatible with all popular e-readers that support apps. An app is available for download. Users will need to make a personal account to use this resource.')
insert into q(q_act,qname,qdesc) values(@actid,N'ICE Video Library',N'Innovative streaming video collections of real patients and therapists created to inspire clinical excellence for faculty, students, and clinicians in occupational therapy and physical therapy programs.')
insert into q(q_act,qname,qdesc) values(@actid,N'India Database',N'ProQuest Indian Journals is a comprehensive, multidisciplinary resource providing full-text, scholarly journals, all published in India. These scholarly sources support many academic fields of study, such as business, medicine, science, technology, social sciences and humanities. Providing a unique source of the very best scholarly periodical output from India, ProQuest Indian Journals is a current resource, with most coverage from the last five years and updated daily with new content.')
insert into q(q_act,qname,qdesc) values(@actid,N'Indigenous Peoples of North America',N'Enabling exploration of the political, social, and cultural history of native peoples from the sixteenth century well into the twentieth century, Indigenous Peoples of North America illustrates the fabric of the North American story with unprecedented depth and breadth. Comprehensive yet personal, the collection covers the history of American Indian tribes and supporting organizations.Topics of interest include trade and communication, Arctic exploration and tribes, the Iroquois Confederation, Canadian Catholic Indian missions, Indian removal, Indian wars and the frontier army, establishment of the Canadian Indian and Aboriginal Department, Indian delegations and Indian-federal relations, Canadian Indian treaty policy, government boarding and missionary schools and curricula, Dawes Severalty and the allotment system, dances and festivals, Alaskan Indian policies, Indian languages and linguistics, assimilation and the Indian New Deal, relocation, termination, and the Indian Claims Commission, water and fishing rights, civil rights, radicalism, poverty, and the American Indian movement.')
insert into q(q_act,qname,qdesc) values(@actid,N'International Newsstream',N'International Newsstream provides the most recent news content outside of the US and Canada, with archives which stretch back decades featuring newspapers, newswires, and news sites in active full-text format. ProQuest International Newsstream provides information from more than 660 of the world''s top newspapers, including The Times (London), The Bangkok Post, El Norte, Financial Times, The Guardian, Jerusalem Post, South China Morning Post, The Daily Telegraph, Asian Wall Street Journal, and the BBC Monitoring series of publications.')
insert into q(q_act,qname,qdesc) values(@actid,N'International Phonetic Alphabet (IPA) Source: Music and Texts',N'For over 15 years, classical singers from around the globe have utilized the IPA Source library for preparation and performance. A trusted resource, our International Phonetic Alphabet catalog is the largest collection of transcribed song and aria texts on the web. With 15,803 titles, IPA source has done the translating and phonetic work for performers to help improve their understanding and pronunciation of foreign language texts, allowing them to focus on technique and communication. IPA Source is always transcribed and translated by hand, not machine.')
insert into q(q_act,qname,qdesc) values(@actid,N'JSTOR',N'Contains core academic journals going back to volume one, but lacking the most recent 3-5 years. Covers fields in the arts, humanities, social sciences, and natural sciences.')
insert into q(q_act,qname,qdesc) values(@actid,N'Just For Kids Access Video',N'Just for Kids includes over 5500 educational videos, audio titles, interactive activities and games, with a focus on early literacy and early elementary students.')
insert into q(q_act,qname,qdesc) values(@actid,N'Kanopy - Faculty Request Only and If Library Budget Allows',N'Kanopy is an on-demand streaming video service featuring a variety of topics from many disciplines. 
insert into q(q_act,qname,qdesc) values(@actid,N'LAIR',N'The Lenoir-Rhyne Academic Institutional Repository (LAIR) is managed by the University Libraries and has been established to preserve and make broadly available the scholarly works of the LR community. LAIR is appropriate for article pre-prints and manuscripts, conference papers, instructional material, as well as student projects, theses, and dissertations. The repository also provides a digital home for the university’s historical and cultural collections.')
insert into q(q_act,qname,qdesc) values(@actid,N'Latin America and Iberia (Spain and Portugal) Database',N'This database provides ongoing full-text academic journals that are locally published by scholarly publishing organizations and educational institutions in many Latin American countries, Spain, and Portugal. Major subject areas of study are represented, including business, science, technology, engineering, social sciences, education, and humanities.')
insert into q(q_act,qname,qdesc) values(@actid,N'LearningExpress Library - College and Career Success Preparation',N'LEL''s PrepSTEP Academic collection features grad school and placement test preparation content, academic skills improvement texts, and career exploration information; requires separate registration.')
insert into q(q_act,qname,qdesc) values(@actid,N'Library Science Database',N'Library Science Database gives users full-text access to a selection of publications relevant to library and information science. It covers a range of titles and topics relevant to the theoretical and applied study of library science, including trade publications aimed at the library profession as well as scholarly journals. Coverage:1970 - current')
insert into q(q_act,qname,qdesc) values(@actid,N'Library, Information Science, and Technical Abstracts with Full Text',N'Library, Information Science & Technology Abstracts (LISTA) with Full Text is a comprehensive database for studies in library and information science. Offering access to 190 active full-text journals, it provides a robust platform for library and information science research.')
insert into q(q_act,qname,qdesc) values(@actid,N'Linguistics Database',N'This database includes full-text journals and other sources in linguistics, including many titles indexed in Linguistics and Language Behavior Abstracts (LLBA). It covers all aspects of the study of language including phonetics, phonology, morphology, syntax and semantics.')
insert into q(q_act,qname,qdesc) values(@actid,N'Literary Reference Center Plus',N'Literary Reference Plus is a full-text literary database providing a complete collection of reference works across all genres and time periods. It contains thousands of poems, short stories, classic novels, plot summaries, critical analysis essays, literary journals, reference books and author biographies, plus lesson plans and literary study guides.')
insert into q(q_act,qname,qdesc) values(@actid,N'Literature Databases - Gale Literature',N'An integrated research experience, Gale Literature brings together Gale''s premier literary databases in a new digital environment that allows researchers, faculty and students to search across these resources to discover and analyze content in entirely new ways. No other publisher offers this unmatched combination of uniquely rich literary content, dependable metadata, and intuitive subject indexing - all enriched by features and design that breathes new life into the study of literature.')
insert into q(q_act,qname,qdesc) values(@actid,N'Literature Resource Center',N'Gale''s Literary Index is a master index to the major literature products published by Gale. It combines and cross-references over 165,000 author names, including pseudonyms and variant names, and listings for over 215,000 titles into one source.')
insert into q(q_act,qname,qdesc) values(@actid,N'Literature: ProQuest Learning',N'ProQuest Learning: Literature supports key student use cases such as introducing students to poets, playwrights, and novelists from diverse backgrounds. Editorially created topic pages include author biographies, literary work summaries and analyses, and genre and movement pages. Journals, magazine, and books provide current, authoritative coverage of famous and lesser-known writers, as well as much-studied literary movements like the Harlem Renaissance, the Beat Generation, and Transcendentalism.')
insert into q(q_act,qname,qdesc) values(@actid,N'MasterFILE Premier',N'MasterFILE Premier contains full text for general reference magazines and publications covering a wide range of subject areas including business, health, education, general science and multicultural issues. It also includes 55,000 full-text primary source documents and more than 2.5 million photos, maps and flags.')
insert into q(q_act,qname,qdesc) values(@actid,N'Materials Science Database',N'Includes information on aerospace and aircraft engineering, casting and molding, ceramics, environmental engineering, metallurgy, nonferrous metals, polymers, plastics, recycling, robots, waste management, and much more.')
insert into q(q_act,qname,qdesc) values(@actid,N'MEDLINEplus',N'MedlinePlus is an online health information resource for patients and their families and friends. It is a service of the National Library of Medicine (NLM), the world''s largest medical library, which is part of the National Institutes of Health (NIH).')
insert into q(q_act,qname,qdesc) values(@actid,N'MEDLINEplus Drugs, Herbs, and Supplements',N'Learn about your prescription drugs and over-the-counter medicines. Includes side effects, dosage, special precautions, and more.')
insert into q(q_act,qname,qdesc) values(@actid,N'Mental Measurements Yearbook',N'Produced by the Buros Center for Testing at the University of Nebraska, this database provides a comprehensive guide to contemporary testing instruments. Designed for an audience ranging from novice test consumers to experienced professionals, the series contains information for evaluating test products in psychology, education, business and leadership. Mental Measurements Yearbook (MMY) includes full-text reviews of 3,000+ contemporary testing instruments, plus all previous editions of the yearbook dating back to 1938 (10,000+ full-text reviews). All MMY entries contain descriptive information (test purpose, publisher, pricing, population and scores) and edited reviews written by leading content area experts. To be included in the MMY, a test must be commercially available, published in the English language and be new or revised since it last appeared in the series.')
insert into q(q_act,qname,qdesc) values(@actid,N'Merck Manual Consumer Version',N'Explains disorders, who is likely to get them, their symptoms, how they''re diagnosed, how they might be prevented, and how they can be treated; also provides information about prognosis.')
insert into q(q_act,qname,qdesc) values(@actid,N'Merck Manual Professional Version',N'Information on medical topics, symptoms, drugs, procedures, news and more, written for the health care professional')
insert into q(q_act,qname,qdesc) values(@actid,N'Middle East and Africa Database',N'This database provides ongoing full-text academic journals that are locally published by scholarly publishing organizations and educational institutions in many Middle Eastern and African countries. Major subject areas of study are represented, including business, science, technology, engineering, social sciences, education, and humanities.')
insert into q(q_act,qname,qdesc) values(@actid,N'Military and Government Collection',N'Military and Government Collection is a database of full-text journals and periodicals pertaining to all branches of the military and government. It is designed to offer current news to military members, analysts, policy makers, students and researchers.')
insert into q(q_act,qname,qdesc) values(@actid,N'Military Database',N'The Military Database covers topics across all government and military branches, including international relations, political science, criminology, defense, aeronautics and space flight, communications, civil engineering, and more. An important benefit of the Military Database is its content diversity. Included are scholarly journals, trade and industry journals, magazines, technical reports, conference proceedings, government publications, and more.')
insert into q(q_act,qname,qdesc) values(@actid,N'MLA International Bibliography',N'MLA International Bibliography covers a broad range of humanities subjects, including world languages and literatures, linguistics, dramatic arts, film, folklore, rhetoric and writing studies, teaching of language, and history of publishing. Its expansive scope also makes it an excellent resource for research in history, philosophy, communications, and cross-disciplinary subjects such as gender studies and area studies. Coverage is international, encompassing scholarly publications in more than 70 languages. Numerous full-text links provide easy access to resources in the library as well as open access publications.')
insert into q(q_act,qname,qdesc) values(@actid,N'Morningstar Investment Research Library',N'Take a closer look at one of the industry’s broadest databases to get data and analysis on stocks, mutual funds, and exchange-traded products.')
insert into q(q_act,qname,qdesc) values(@actid,N'National Center for Complementary and Integrative Health',N'The National Center for Complementary and Integrative Health (NCCIH) is the Federal Government''s lead agency for scientific research on complementary and alternative medicine (CAM). The mission of NCCIH is to determine, through rigorous scientific investigation, the fundamental science, usefulness, and safety of complementary and integrative health approaches and their roles in improving health and health care. NCCIH’s vision is that scientific evidence informs decision making by the public, health care professionals, and health policymakers regarding the integrated use of complementary health approaches in a whole person health framework.')
insert into q(q_act,qname,qdesc) values(@actid,N'Naxos Music Library',N'Naxos Music Library [NML] is the world´s largest online classical music library. Currently, it offers streaming access to more than 186,291 CDs with more than 2,864,669 tracks of both standard and rare repertoire. Over 600 new titles are being added to the library each month. The library offers the complete Naxos and Marco Polo catalogues plus the complete catalogues or selected titles from over 950 record labels, with more labels joining every month. Along with classical music, jazz, world, and pop/rock are also represented. NML can be accessed from any computer, anywhere, anytime. The contents can be browsed by composer, artist, genre, category and label. User can search with our fast and easy-to-use keyword search engine, or by our sophisticated advanced search engine with up to 14 search criteria. In addition to listening to recordings, NML provides liner notes for many albums. Listeners can create personalized playlists or enjoy our predefined Naxos Music Library playlists.')
insert into q(q_act,qname,qdesc) values(@actid,N'Naxos Video Library',N'The world''s leading performing arts distributor brings you an extensive streaming video library of classical music performances - operas, ballets, concerts, dances, documentaries and many more. Watch fine productions from the world''s greatest opera houses, ballet and dance companies, orchestras, artists, festivals and concert halls on demand.')
insert into q(q_act,qname,qdesc) values(@actid,N'Naxos Works Database',N'Use the database to find details about composers and their works, instrumentations, durations, publishers and work introductions. A fantastic research tool for students, programmers, conductors and performers.')
insert into q(q_act,qname,qdesc) values(@actid,N'NC Health Info',N'NC Health Info aims to help North Carolina citizens make informed decisions about their health. On our site you will find reliable and easy-to-understand information on topics like health conditions, low and no-cost treatment options, and where to find providers and services in North Carolina. All resources have been carefully selected by volunteer librarians.')
insert into q(q_act,qname,qdesc) values(@actid,N'NCpedia',N'NCpedia highlights North Carolina''s unique resources, people, and culture to enrich, educate and inform. It is coordinated and managed by the North Carolina Government and Heritage Library at the State Library of North Carolina, a part of the North Carolina Department of Natural and Cultural Resources. The encyclopedia contains articles covering a broad spectrum of topics and resources about North Carolina, including: historical time periods, subjects, and events; biographies, including North Carolina''s governors; counties and government; geography and environment; business and economy; historical places and monuments; natural resources and natural heritage; and many others. NCpedia also includes thousands of images. Contributors include professional and independent historians, librarians and archivists, museum professionals and many subject specialists.')
insert into q(q_act,qname,qdesc) values(@actid,N'New York Times',N'Includes all the articles published since the first issue of the paper in 1851. Provides full text and full image articles with digital reproductions of every page, every article and every issue in PDF format. In addition to news stories, includes editorials, letters to the editor, obituaries, birth and marriage announcements, photos, and advertisements.')
insert into q(q_act,qname,qdesc) values(@actid,N'Newspaper Source Plus',N'Newspaper Source Plus provides a full-text digital collection of the world''s major news content. It includes millions of articles from newspapers and newswires and offers television and radio transcripts and ongoing daily updates from popular news sources.')
insert into q(q_act,qname,qdesc) values(@actid,N'North American Women''s Letters and Diaries',N'This collection includes the immediate experiences of 1,325 women and 150,000 pages of diaries and letters. Particular care has been taken to index this material so that it can be searched more thoroughly than ever before. The materials have been carefully chosen using leading bibliographies, supplemented by customer requests and more than 7,000 pages of previously unpublished material. The collection also includes biographical sketches of people represented in this database.')
insert into q(q_act,qname,qdesc) values(@actid,N'NoveList Plus',N'NoveList, the complete readers'' advisory solution, empowers librarians, engages readers and connects communities.')
insert into q(q_act,qname,qdesc) values(@actid,N'NUMDAM',N'You can find on this website the full text of mathematical research documents: journal articles, seminar and conference proceedings, books and monographs, doctoral theses. While a large part of the content has been digitized starting first known issue from paper volumes, the library acquires newer content provided by their publishers in order to keep the archive alive and reasonably current. Full texts are freely downloadable immediately or after a variable moving wall.')
insert into q(q_act,qname,qdesc) values(@actid,N'Nursing and Allied Health Database',N'This database offers reliable, comprehensive coverage of the fields of nursing and allied health including journals, video, dissertations, reference books and more.')
insert into q(q_act,qname,qdesc) values(@actid,N'Nutrition Care Manual',N'NCM is a professional practice resource from the Academy of Nutrition and Dietetics, containing nutrition education materials and current evidence-based nutrition recommendations for adults.')
insert into q(q_act,qname,qdesc) values(@actid,N'Omnigraphics Health Reference Sourcebooks',N'Quality reference publications for library, schools and research markets covering the areas of biography, history, health, culture, finance, and more.')
insert into q(q_act,qname,qdesc) values(@actid,N'OpenDissertations',N'EBSCO Open Dissertations makes electronic theses and dissertations (ETDs) more accessible to researchers worldwide. The free portal is designed to benefit universities and their students and make ETDs more discoverable.')
insert into q(q_act,qname,qdesc) values(@actid,N'Our State Magazine Collection',N'Explore past issues of Our State, one of North Carolina''s longest running and most popular magazines. First published in 1933, The State (as it was known until 1996) features stories about North Carolina''s people, places, and history.')
insert into q(q_act,qname,qdesc) values(@actid,N'Oxford English Dictionary',N'An unsurpassed guide for researchers in any discipline to the meaning, history, and usage of over 500,000 words and phrases across the English-speaking world.')
insert into q(q_act,qname,qdesc) values(@actid,N'Oxford Music Online',N'Welcome to Oxford Music Online, home of Grove Music Online, the world’s premier online music encyclopedia, offering comprehensive coverage of music, musicians, music-making, and music scholarship.')
insert into q(q_act,qname,qdesc) values(@actid,N'Oxford Reference',N'As you browse through Oxford Reference, you may find results that range from short-entry, general reference to more in-depth articles on specialized subjects. Oxford Reference is the premier online reference product, spanning 22 different subject areas, bringing together 2 million digitized entries across Oxford University Press’s Dictionaries, Companions and Encyclopedias.')
insert into q(q_act,qname,qdesc) values(@actid,N'PBS Video Collection',N'PBS and our member stations are America’s largest classroom, the nation’s largest stage for the arts and a trusted window to the world')
insert into q(q_act,qname,qdesc) values(@actid,N'Pediatric Nutrition Care Manual',N'PNCM is a professional practice resource from the Academy of Nutrition and Dietetics containing nutrition education materials and current evidence-based nutrition recommendations for children.')
insert into q(q_act,qname,qdesc) values(@actid,N'Points of View',N'Containing resources that present multiple sides of an issue, Points of View Reference Source provides rich content that can help students assess and develop persuasive arguments and essays, better understand controversial issues and develop analytical thinking skills.')
insert into q(q_act,qname,qdesc) values(@actid,N'Political Science Database',N'Political Science Database gives users access to hundreds of leading political science, public policy, and international relations journals. It also includes thousands of recent full-text doctoral dissertations on political science topics, together with working papers, conference proceedings, country reports, policy papers and other sources. Coverage: 1985 - current')
insert into q(q_act,qname,qdesc) values(@actid,N'Project MUSE',N'Project MUSE promotes the creation and dissemination of essential humanities and social science resources through collaboration with libraries, publishers, and scholars worldwide. Forged from a partnership between a university press and a library, Project MUSE is a trusted part of the academic and scholarly community it serves.')
insert into q(q_act,qname,qdesc) values(@actid,N'ProQuest Central',N'ProQuest Central is the largest single periodical resource available, bringing together complete databases across all major subject areas, including Business, Health and Medical, Language and Literature, Social Sciences, Education, Science and Technology, as well as core titles in the Performing and Visual Arts, History, Religion, Philosophy, and includes thousands of full-text newspapers from around the world.')
insert into q(q_act,qname,qdesc) values(@actid,N'ProQuest Research Library',N'ProQuest Research Library provides one-stop access to thousands of full-text periodicals from one of the broadest, most inclusive general reference databases ProQuest has to offer. Search from a highly-respected, diversified mix of scholarly journals, professional and trade publications, and magazines covering over 150 subjects and topics. in all instances.')
insert into q(q_act,qname,qdesc) values(@actid,N'PsycARTICLES',N'Delve into the science of psychology and behavior with APA PsycArticles, the database of full-text peer-reviewed articles published by the American Psychological Association and affiliated journals.')
insert into q(q_act,qname,qdesc) values(@actid,N'Psychology Database',N'This database provides abstracts and indexing for key Psychology titles, many which are available in full text. Many titles are indexed in PsycINFO. Coverage ranges from behavioral, clinical, cognitive, developmental, experimental, industrial and social psychology, along with personality, psychobiology and psychometrics.')
insert into q(q_act,qname,qdesc) values(@actid,N'Psychotherapy.net',N'This link provides access to our three Psychotherapy.net videos, on "Understanding Group Psychotherapy," by Irving Yalom.')
insert into q(q_act,qname,qdesc) values(@actid,N'PsycINFO',N'This ever-expanding collection of behavioral and social science research, dissertations, and scholarly literature abstracts offers a broad view of the field. With relevance to a host of related disciplines, including neuroscience, business, nursing, law and education, APA PsycInfo delivers the peer-reviewed content and abstracts students and researchers need, and does so with remarkable precision and a dedication to scholarly and scientific excellence.')
insert into q(q_act,qname,qdesc) values(@actid,N'Public Health Database',N'ProQuest Public Health covers a wide variety of disciplines ranging from social sciences and biological sciences to business. Journal results are indexed from core literature collected from a variety of publishers using appropriate public-health terminology.')
insert into q(q_act,qname,qdesc) values(@actid,N'PubMed',N'PubMed comprises more than 38 million citations for biomedical literature from MEDLINE, life science journals, and online books. Citations may include links to full text content from PubMed Central and publisher web sites.')
insert into q(q_act,qname,qdesc) values(@actid,N'R2 Digital Library',N'The R2 Digital Library is a market-leading eBook platform for health science collections featuring a comprehensive collection of medical, nursing and allied health eBooks presented through a clean and intuitive interface.')
insert into q(q_act,qname,qdesc) values(@actid,N'Regional Business News',N'Regional Business News provides full-text regional business publications for the United States and Canadian provinces. Users can search newspapers, magazines and other resources from trusted news sources.')
insert into q(q_act,qname,qdesc) values(@actid,N'Religion Database',N'Religion Database provides a wide range of primarily full-text periodicals and other sources for diverse religious and spiritual studies, covering formal theological studies and commentary on topics of general interest from the perspectives of many worldwide religions. As well as scholarly journals there are many titles from religious publishing bodies and nondenominational organizations. The resource reflects a wide spectrum of religious belief systems and supports the global study of religion. Coverage: 1986 - current')
insert into q(q_act,qname,qdesc) values(@actid,N'Research Companion - ProQuest',N'ProQuest Research Companion is an intuitive, and self-guided product that supports information literacy, writing, and research skills instruction occurring in today''s libraries and online learning environments.')
insert into q(q_act,qname,qdesc) values(@actid,N'Sanborn Maps North Carolina',N'Sanborn Maps North Carolina is a collection of historical fire insurance maps for various communities throughout North Carolina, with coverage as early as 1876 and as recent as 1970 "for anyone who wants to learn about the history, growth, and development of American cities, towns, and neighborhoods."')
insert into q(q_act,qname,qdesc) values(@actid,N'SIRS Discoverer',N'A multidisciplinary database specifically designed for learners, researchers, and educators covering curriculum areas including history, health, language arts, math, science, social studies, and technology.')
insert into q(q_act,qname,qdesc) values(@actid,N'SIRS Issues Researcher',N'SIRS Issues Researcher delivers diverse perspectives on today’s complex social issues with relevant, credible information and tools that equip students to think critically about global controversies. Get right to the heart of an issue with special Leading Issues coverage. SIRS Issues Researcher provides not only the background information necessary to understanding an issue’s origins and key points of contention, but also the current analysis that illuminates how the issue affects politics, personal beliefs, and current events.')
insert into q(q_act,qname,qdesc) values(@actid,N'Slavery in America',N'Introduction to U.S. History: Slavery in America is a digital collection of over 600 documents in 75,000 pages selected by Vernon Burton and Troy Smith from the University of Illinois at Urbana-Champaign, and drawn from the Sabin collection and other Gale sources. This project documents key aspects of the history of slavery in America from its origins in Africa to its abolition, including materials on the slave trade, plantation life, emancipation, pro-slavery and anti-slavery arguments, the religious views on slavery, etc.
insert into q(q_act,qname,qdesc) values(@actid,N'Social Science Database',N'Social Science Database offers indexing and full text for hundreds of academic journals, providing extensive coverage across a wide range of social science disciplines including anthropology, communication, criminology, economics, education, political science, psychology, social work, and sociology.')
insert into q(q_act,qname,qdesc) values(@actid,N'Sociology Database',N'Sociology Database covers the international literature of sociology and social work, including relevant titles from related fields such as social policy, social care, social services, social anthropology, gender studies, gerontology, social psychology and population studies. It includes hundreds of full-text scholarly journals, as well as dissertations and other sources. Coverage: 1985 - current')
insert into q(q_act,qname,qdesc) values(@actid,N'SportDiscus',N'The definitive database for sports and sports medicine research. Providing hundreds of full-text sports medicine journals, it is an essential tool for health professionals and researchers studying fitness, health and sports.')
insert into q(q_act,qname,qdesc) values(@actid,N'Sports Nutrition Care Manual',N'SNCM is a professional practice resource from the Academy of Nutrition and Dietetics containing nutrition education materials and current evidence-based nutrition recommendations for athletes.')
insert into q(q_act,qname,qdesc) values(@actid,N'Springer E-Books',N'The Springer eBook collection delivers complete access to a collection of scientific, technical and medical publications.')
insert into q(q_act,qname,qdesc) values(@actid,N'Springerlink Journals',N'Peer-reviewed Journals in a variety of subjects, with hundreds of titles in the health, life, and physical sciences, as well as limited coverage of the social sciences and humanities')
insert into q(q_act,qname,qdesc) values(@actid,N'State Demographer',N'The State Demographer produces annual estimates of our current state, municipal, and county populations.')
insert into q(q_act,qname,qdesc) values(@actid,N'Statesman''s Yearbook',N'The Statesman’s Yearbook is an annual hardback publication covering the politics, cultures and economies of all of the countries of the world plus major international organizations. It is authoritative and up-to-date; meticulously compiled by a dedicated in-house editorial team since 1864.')
insert into q(q_act,qname,qdesc) values(@actid,N'Statistical Abstract of the U.S.',N'The ProQuest Statistical Abstract of the United States is the authoritative and comprehensive summary of statistics on the social, political and economic conditions of the United States.')
insert into q(q_act,qname,qdesc) values(@actid,N'Swank Streaming Film Collection - Faculty request only and if library budget allows',N'Streaming collection of films, documentaries and TV shows, available both on and off campus.')
insert into q(q_act,qname,qdesc) values(@actid,N'Telecommunications Database',N'This database is an essential resource for anyone researching the industry or its technology. Whether you’re looking for the latest news on WAP technology, following market penetration of new technologies, or gathering information about the key players in this field, ProQuest Telecommunications helps you stay one step ahead. The database includes over 140 titles, with more than 115 available in full text. Search more than 600,000 records, dating back to the early 1990''s. Coverage: 1995 - current.')
insert into q(q_act,qname,qdesc) values(@actid,N'Transparent Language',N'"Transparent Language Online provides a fun, effective, and engaging experience for learners of all levels looking to build their listening, speaking, reading, and writing skills in over 110 non-English languages. Combining robust courses, supplemental vocabulary, extensive grammar resources, and mobile apps, Transparent Language Online is the most complete language-learning system."
insert into q(q_act,qname,qdesc) values(@actid,N'Turkey Database',N'This database provides ongoing full-text academic journals that are locally published by scholarly publishing organizations and educational institutions in Turkey. Major subject areas of study are represented, including business, science, technology, engineering, social sciences, education, and humanities.')
insert into q(q_act,qname,qdesc) values(@actid,N'United Kingdom and Ireland Database',N'This database provides ongoing full-text academic journals that are locally published by scholarly publishing organizations and educational institutions in the United Kingdom and the Republic of Ireland. Major subject areas of study are represented, including business, science, technology, engineering, social sciences, education, and humanities.')
insert into q(q_act,qname,qdesc) values(@actid,N'US Newsstream',N'U.S. Newsstream enables users to search the most recent premium U.S. news content, as well as archives which stretch back into the 1980s featuring newspapers, newswires, blogs, and news sites in active full-text format. For academic and public libraries, U.S. Newsstream offers exclusive access to the Los Angeles Times, Chicago Tribune, and co-exclusive access (with Factiva) to The Wall Street Journal. U.S. Newsstream also offers one of the largest collections of local and regional newspapers, and is cross-searchable on the ProQuest platform. Coverage: 1980 - current.')
insert into q(q_act,qname,qdesc) values(@actid,N'Wall Street Journal',N'The Wall Street Journal was founded in July 1889. Ever since, the Journal has led the way in chronicling the rise of industries in America and around the world. In no other period of human history has the planet witnessed changes so dramatic or swift. The Journal has covered the births and deaths of tens of thousands of companies; the creation of new industries such as autos, aerospace, oil and entertainment; two world wars and numerous other conflicts; profound advances in science and technology; revolutionary social movements; the rise of consumer economies in the U.S. and abroad; and the fitful march of globalization.')
insert into q(q_act,qname,qdesc) values(@actid,N'Washington Post',N'This publication''s detailed indexing helps users quickly find the news information they need. Each issue is indexed thoroughly, so they have access to not only top news stories but also the information contained on the various sections of the paper. The indexing covers not only complete bibliographic information but also companies, people, products, and more. Coverage: 1987 - current.')
insert into q(q_act,qname,qdesc) values(@actid,N'Wildlife and Ecology Studies Worldwide',N'Wildlife and Ecology Studies Worldwide is the largest index to literature about wild mammals, birds, reptiles and amphibians. It covers many wildlife subjects including individual species, habitat types, wildlife behavior, ecotourism and zoology.')
insert into q(q_act,qname,qdesc) values(@actid,N'Wiley Online Library',N'Multidisciplinary collection of online resources covering life, health and physical sciences, social science, and the humanities.')
insert into q(q_act,qname,qdesc) values(@actid,N'WorldCat',N'Search the collections and services of more than 10,000 libraries worldwide.')
